// The lines the affirmations room shows. Two corpora fit this shape:
//
//   lines.local.ts   the real one — Louise Hay's affirmations, generated by
//                    tools/build-affirmations.mjs from her published pages. A
//                    personal build only: gitignored and never committed,
//                    because her lines are under copyright.
//   lines.sample.ts  placeholder lines written for this repo, so a fresh clone
//                    builds, runs and tests.
//
// The local file wins when it exists. The require is optional (Metro bundles it
// only if the file is there; see metro.config.js), and Jest is pointed away from
// it (jest/no-local-corpus.js), so the suite is the same on every machine.
import * as sample from './lines.sample';

export interface AffirmationSource {
  readonly author: string;
  readonly urls: readonly string[];
}

interface Corpus {
  readonly SOURCE: AffirmationSource;
  readonly LINES: readonly string[];
}

const load = (): { corpus: Corpus; kind: 'full' | 'sample' } => {
  try {
    return { corpus: require('./lines.local') as Corpus, kind: 'full' };
  } catch {
    return { corpus: sample, kind: 'sample' };
  }
};

const loaded = load();

export const SOURCE: AffirmationSource = loaded.corpus.SOURCE;
export const LINES: readonly string[] = loaded.corpus.LINES;
export const CORPUS: 'full' | 'sample' = loaded.kind;
